{
 "summary": "The main theorem formalizes Theorem 1.1. For n ≥ 1, every convex compact S ⊂ ℝⁿ with nonempty interior, barycenter 0, and int(S) ∩ ℤⁿ = {0} has Lebesgue volume at most (n+1)ⁿ/n!. A separate theorem states that the bound is attained by some such body. The most important caveat is that `centeredSimplex` is defined with dilation factor (n+2), not the paper's (n+1). With that definition the two simplex lemmas (barycenter 0, volume (n+1)ⁿ/n!) look false for n ≥ 1, so either the definition is wrong or something unexpected is going on, and a probe is needed.",
 "glossary": [
  {"decl": "Space", "line": 10, "plain": "ℝⁿ as Fin n → ℝ (sup-norm product topology, product Lebesgue measure)", "standard_concept": "ℝⁿ", "matches_standard": "yes", "note": "Topology and measure agree with the Euclidean ones."},
  {"decl": "integerPoint", "line": 12, "plain": "inclusion ℤⁿ → ℝⁿ", "standard_concept": "lattice ℤⁿ ⊂ ℝⁿ", "matches_standard": "yes", "note": ""},
  {"decl": "standardSimplex", "line": 15, "plain": "Δn = {x ≥ 0, Σ xᵢ ≤ 1} = conv{0, e1, …, en}", "standard_concept": "Δn", "matches_standard": "yes", "note": ""},
  {"decl": "simplexDilation", "line": 18, "plain": "x ↦ (n+2)x − (1, …, 1)", "standard_concept": "x ↦ (n+1)x − (1, …, 1)", "matches_standard": "no", "note": "The paper's sharp simplex is (n+1)Δn − (1, …, 1); Lean uses factor n+2."},
  {"decl": "centeredSimplex", "line": 21, "plain": "(n+2)Δn − (1, …, 1)", "standard_concept": "(n+1)Δn − (1, …, 1)", "matches_standard": "no", "note": "Lean's version has barycenter (1/(n+1))·𝟙 ≠ 0 and volume (n+2)ⁿ/n! for n ≥ 1."},
  {"decl": "normalizedVolume", "line": 24, "plain": "Lebesgue volume, as a real number via toReal (∞ ↦ 0)", "standard_concept": "vol", "matches_standard": "yes", "note": "Not 'normalized' despite the name. This is harmless for compact sets."},
  {"decl": "barycenter", "line": 27, "plain": "vol(K)⁻¹ ∫_K x dx (junk value 0 if vol = 0)", "standard_concept": "barycenter", "matches_standard": "yes", "note": "Correct for full-dimensional compact K."},
  {"decl": "interiorLatticePoints", "line": 30, "plain": "{z ∈ ℤⁿ : z ∈ int K}", "standard_concept": "int(K) ∩ ℤⁿ", "matches_standard": "yes", "note": ""},
  {"decl": "CenteredBody", "line": 33, "plain": "convex compact K with nonempty interior, barycenter 0, int(K) ∩ ℤⁿ = {0}", "standard_concept": "Hypothesis class of Theorem 1.1", "matches_standard": "yes", "note": ""},
  {"decl": "sharpConstant", "line": 41, "plain": "(n+1)ⁿ/n!", "standard_concept": "(n+1)ⁿ/n!", "matches_standard": "yes", "note": ""}
 ],
 "lean_claims": [
  {"theorem": "Ehrhart.SimplexVolume.barycenter_centeredSimplex", "line": 48, "plain": "For all n, the barycenter of (n+2)Δn − 𝟙 is 0."},
  {"theorem": "Ehrhart.SimplexVolume.normalizedVolume_centeredSimplex", "line": 52, "plain": "For n > 0, vol((n+2)Δn − 𝟙) = (n+1)ⁿ/n!."},
  {"theorem": "Ehrhart.SimplexVolume.exists_centeredBody_sharp", "line": 56, "plain": "For n > 0, there is a convex compact full-dimensional K ⊂ ℝⁿ with barycenter 0 and int(K) ∩ ℤⁿ = {0} whose volume equals (n+1)ⁿ/n!."},
  {"theorem": "Ehrhart.Volume.ehrhart_volume_inequality_for_sets", "line": 65, "plain": "For n > 0 and S ⊂ ℝⁿ convex, compact, with nonempty interior, barycenter 0 and int(S) ∩ ℤⁿ = {0}: vol(S) ≤ (n+1)ⁿ/n!."}
 ],
 "paper_claims": [
  {"ref": "Theorem 1.1", "plain": "A full-dimensional compact convex K ⊂ ℝⁿ with barycenter 0 and int(K) ∩ ℤⁿ = {0} has vol(K) ≤ (n+1)ⁿ/n!."},
  {"ref": "Sharpness remark after Thm 1.1", "plain": "(n+1)Δn − (1, …, 1) has barycenter 0, no other interior lattice point, and volume (n+1)ⁿ/n!."}
 ],
 "coverage": [
  {"paper_ref": "Theorem 1.1", "lean_theorem": "Ehrhart.Volume.ehrhart_volume_inequality_for_sets", "relation": "equivalent", "why": "Same hypotheses and conclusion. The n > 0 restriction is immaterial, since n = 0 is trivial."},
  {"paper_ref": "Sharpness remark after Thm 1.1", "lean_theorem": "Ehrhart.SimplexVolume.exists_centeredBody_sharp", "relation": "lean_weaker", "why": "Asserts only that some extremal body exists; it does not identify it as the simplex."},
  {"paper_ref": "Sharpness remark after Thm 1.1", "lean_theorem": "Ehrhart.SimplexVolume.barycenter_centeredSimplex", "relation": "different", "why": "Concerns (n+2)Δn − 𝟙, not (n+1)Δn − 𝟙."},
  {"paper_ref": "Sharpness remark after Thm 1.1", "lean_theorem": "Ehrhart.SimplexVolume.normalizedVolume_centeredSimplex", "relation": "different", "why": "Concerns (n+2)Δn − 𝟙, whose volume is (n+2)ⁿ/n!."}
 ],
 "flags": [
  {"id": "F1", "category": "definition-mismatch", "severity": "high", "decl": "simplexDilation", "line": 19, "paper_ref": "Sharpness remark after Thm 1.1", "explanation": "The dilation factor is (n+2), whereas the paper uses (n+1)Δn − (1, …, 1). For n = 1 this gives [−1, 2], with barycenter 1/2 and length 3 ≠ 2 = sharpConstant 1. In general the barycenter is (1/(n+1))·𝟙 and the volume is (n+2)ⁿ/n!. Both simplex lemmas therefore appear false as stated for n ≥ 1, so they cannot faithfully encode the paper's sharpness simplex.", "polarity": "unclear", "probe_idea": "Prove normalizedVolume (centeredSimplex 1) = 3, and barycenter (centeredSimplex 1) = fun _ => 1/2. Both contradict the stated lemmas."},
  {"id": "F2", "category": "coverage", "severity": "low", "decl": "Ehrhart.SimplexVolume.exists_centeredBody_sharp", "line": 56, "paper_ref": "Sharpness remark after Thm 1.1", "explanation": "Sharpness is stated only existentially and does not depend on centeredSimplex. It establishes sharpness of the bound but does not identify the extremizer as the paper's simplex.", "polarity": "lean weaker", "probe_idea": null},
  {"id": "F3", "category": "assumption", "severity": "low", "decl": "Ehrhart.Volume.ehrhart_volume_inequality_for_sets", "line": 66, "paper_ref": "Theorem 1.1", "explanation": "The hypothesis 0 < n is not stated in the paper. The n = 0 case is trivial (volume 1 = 1⁰/0!), so this is immaterial.", "polarity": "lean weaker", "probe_idea": null}
 ],
